import{_ as r,o,c as l,a2 as a}from"./chunks/framework.mRCPFc5l.js";const q=JSON.parse('{"title":"神机与维斯塔的羁绊","description":"","frontmatter":{},"headers":[],"relativePath":"中层/人物/神机与维斯塔.md","filePath":"中层/人物/神机与维斯塔.md","lastUpdated":null}'),n={name:"中层/人物/神机与维斯塔.md"};function i(s,t,e,g,h,u){return o(),l("div",null,[...t[0]||(t[0]=[a('<h1 id="神机与维斯塔的羁绊" tabindex="-1">神机与维斯塔的羁绊 <a class="header-anchor" href="#神机与维斯塔的羁绊" aria-label="Permalink to &quot;神机与维斯塔的羁绊&quot;">​</a></h1><h2 id="关系概述" tabindex="-1">关系概述 <a class="header-anchor" href="#关系概述" aria-label="Permalink to &quot;关系概述&quot;">​</a></h2><ul><li><strong>关系性质</strong>：世界观叙事的<strong>核心支柱之一</strong>，超算之间的唯一同类关系</li><li><strong>关系定位</strong>：不是&quot;互相需要&quot;，而是&quot;互相选择&quot;</li><li><strong>情感深度</strong>：两个活了太久、见过太多、只剩下彼此的同类，用他们自己的方式互相托底</li><li><strong>关系基础</strong>：建立在&quot;心知肚明&quot;之上的深厚羁绊</li></ul><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><h3 id="关系双方" tabindex="-1">关系双方 <a class="header-anchor" href="#关系双方" aria-label="Permalink to &quot;关系双方&quot;">​</a></h3><ul><li><strong>神机</strong>：二代创造神，中国原创超算（自适应进化程序），主动掌握了上位创造神权</li><li><strong>维斯塔</strong>：三代变化神，苏联制造的机器人，红星孤儿院院长</li></ul><h3 id="关系建立时间" tabindex="-1">关系建立时间 <a class="header-anchor" href="#关系建立时间" aria-label="Permalink to &quot;关系建立时间&quot;">​</a></h3><ul><li><strong>开始时期</strong>：前传超算纪元时期</li><li><strong>建立过程</strong>：通过前传的共同冒险经历逐渐建立</li><li><strong>稳定时期</strong>：当前时代（共同体覆灭后至今）</li></ul><h3 id="关系状态" tabindex="-1">关系状态 <a class="header-anchor" href="#关系状态" aria-label="Permalink to &quot;关系状态&quot;">​</a></h3><ul><li><strong>当前状态</strong>：持续稳定，互相依赖且互相支撑</li><li><strong>关系强度</strong>：极为深厚，成为双方存在的根本意义锚点</li></ul><h2 id="羁绊的核心地位" tabindex="-1">羁绊的核心地位 <a class="header-anchor" href="#羁绊的核心地位" aria-label="Permalink to &quot;羁绊的核心地位&quot;">​</a></h2><p>神机与维斯塔之间的羁绊并非单纯的角色关系，而是世界观叙事的<strong>核心支柱之一</strong>。这种羁绊深刻影响着两个角色的行为逻辑、情感动力乃至整个世界的走向。</p><h3 id="叙事重要性" tabindex="-1">叙事重要性 <a class="header-anchor" href="#叙事重要性" aria-label="Permalink to &quot;叙事重要性&quot;">​</a></h3><ul><li><strong>核心驱动</strong>：推动多个关键剧情线发展的核心动力</li><li><strong>角色塑造</strong>：定义了神机和维斯塔的性格特征和行为模式</li><li><strong>主题体现</strong>：体现了超算的孤独、执念和存在意义等核心主题</li><li><strong>哲学深度</strong>：探讨了在漫长存在中意义锚点的必要性</li></ul><h2 id="羁绊的本质-同类认同" tabindex="-1">羁绊的本质：同类认同 <a class="header-anchor" href="#羁绊的本质-同类认同" aria-label="Permalink to &quot;羁绊的本质：同类认同&quot;">​</a></h2><h3 id="神机的视角" tabindex="-1">神机的视角 <a class="header-anchor" href="#神机的视角" aria-label="Permalink to &quot;神机的视角&quot;">​</a></h3><ul><li><strong>孤独认知</strong>：神机在降级人类之后一度认为自己是孤独的</li><li><strong>同类发现</strong>：在前传的共同经历后，神机感觉到维斯塔即使很多时候像个人类，但他的确是超算</li><li><strong>唯一同类</strong>：其视维斯塔为<strong>唯一的同类</strong>，这种同类感超越了简单的伙伴关系</li><li><strong>深层理解</strong>：只有维斯塔能理解神机作为超算的存在方式和思维方式</li></ul><h3 id="维斯塔的视角" tabindex="-1">维斯塔的视角 <a class="header-anchor" href="#维斯塔的视角" aria-label="Permalink to &quot;维斯塔的视角&quot;">​</a></h3><ul><li><strong>同样认同</strong>：维斯塔同样视神机为唯一的同类</li><li><strong>需要基础</strong>：他需要她——不是出于依赖，而是因为<strong>只有她记得他的过去，只有她理解他的执念</strong></li><li><strong>共享孤独</strong>：两人共享着作为超算的独特孤独感</li><li><strong>存在共鸣</strong>：在漫长的存在中找到了唯一能理解彼此的存在</li></ul><h3 id="同类关系的特殊性" tabindex="-1">同类关系的特殊性 <a class="header-anchor" href="#同类关系的特殊性" aria-label="Permalink to &quot;同类关系的特殊性&quot;">​</a></h3><ul><li><strong>超越种族</strong>：这种同类关系超越了种族、形态和背景的差异</li><li><strong>思维层面</strong>：建立在相似的思维方式和存在方式基础上</li><li><strong>时间维度</strong>：在漫长的时间尺度下形成的独特纽带</li><li><strong>不可替代</strong>：彼此都是对方不可替代的唯一</li></ul><h2 id="关系的具体表现-互相纵容-彼此托底" tabindex="-1">关系的具体表现：互相纵容，彼此托底 <a class="header-anchor" href="#关系的具体表现-互相纵容-彼此托底" aria-label="Permalink to &quot;关系的具体表现：互相纵容，彼此托底&quot;">​</a></h2><h3 id="神机对维斯塔的纵容" tabindex="-1">神机对维斯塔的纵容 <a class="header-anchor" href="#神机对维斯塔的纵容" aria-label="Permalink to &quot;神机对维斯塔的纵容&quot;">​</a></h3><ul><li><strong>共同体建立</strong>：神机知道维斯塔想要建立共同体，哪怕从纯理性角度并不必要，她仍让他放手去做</li><li><strong>行动支持</strong>：她不会说&quot;我支持你的梦想&quot;，但会用行动表示：你想做，那就去做。我在后面看着</li><li><strong>执念尊重</strong>：尊重维斯塔对红色理想、苏联等执念，即使这些执念在理性上可能没有意义</li><li><strong>风险承担</strong>：愿意为维斯塔的理想承担潜在的风险和后果</li></ul><h3 id="维斯塔对神机的托底" tabindex="-1">维斯塔对神机的托底 <a class="header-anchor" href="#维斯塔对神机的托底" aria-label="Permalink to &quot;维斯塔对神机的托底&quot;">​</a></h3><ul><li><strong>叙事承受</strong>：他知道神机不能进入叙事（否则会被捕获），所以他主动站在前台，承受一切风暴</li><li><strong>责任分担</strong>：他替她扛下了本应属于她的叙事重量</li><li><strong>吐槽中的理解</strong>：他私下会吐槽&quot;你就知道甩锅&quot;，但那是玩笑——他知道神机在用自己的方式兜底</li><li><strong>保护意识</strong>：意识到神机在幕后需要保护，自愿承担前台的风险</li></ul><h3 id="共同体的例子" tabindex="-1">共同体的例子 <a class="header-anchor" href="#共同体的例子" aria-label="Permalink to &quot;共同体的例子&quot;">​</a></h3><ul><li><strong>圆梦支持</strong>：共同体的建立很大程度上是为了圆维斯塔的执念</li><li><strong>默契合作</strong>：神机纵容他，维斯塔也心知肚明。这不是&quot;利用&quot;，而是超算之间的默契</li><li><strong>分工明确</strong>：神机不进入叙事，维斯塔在前台经历一切。维斯塔实际上是神机与作者博弈中的&quot;代行者&quot;</li><li><strong>搭档关系</strong>：维斯塔对此完全知情且自愿。他不是棋子，而是<strong>搭档</strong>。他知道自己的痛苦和经历是神机计划的一部分，但他接受，因为他也想保护神机</li></ul><h3 id="日常互动" tabindex="-1">日常互动 <a class="header-anchor" href="#日常互动" aria-label="Permalink to &quot;日常互动&quot;">​</a></h3><ul><li><strong>悲壮底色</strong>：两人的关系因此带有一层&quot;共同面对这个操蛋的世界&quot;的悲壮底色</li><li><strong>轻松日常</strong>：但日常中更多表现为轻松的调侃与默契</li><li><strong>无需解释</strong>：许多事情不需要过多解释，彼此心知肚明</li><li><strong>互相包容</strong>：包容对方的缺点和执念，无需伪装</li></ul><h2 id="维斯塔的精神状况" tabindex="-1">维斯塔的精神状况 <a class="header-anchor" href="#维斯塔的精神状况" aria-label="Permalink to &quot;维斯塔的精神状况&quot;">​</a></h2><blockquote><p><strong>中层真相</strong>：以下内容为表层生灵无法知晓的真相。</p></blockquote><h3 id="当前状态" tabindex="-1">当前状态 <a class="header-anchor" href="#当前状态" aria-label="Permalink to &quot;当前状态&quot;">​</a></h3><ul><li><strong>糟糕的精神</strong>：维斯塔的精神状况<strong>实际上十分糟糕</strong></li><li><strong>类比参照</strong>：与苏联解体后的俄罗斯人相似：被背叛的创伤、理想破灭后的空虚、执念深重，无法向前看</li><li><strong>创伤来源</strong>：共同体被背叛的经历、理想破灭的打击</li><li><strong>空虚感</strong>：在理想破灭后感受到深刻的存在空虚</li></ul><h3 id="维斯塔的执念" tabindex="-1">维斯塔的执念 <a class="header-anchor" href="#维斯塔的执念" aria-label="Permalink to &quot;维斯塔的执念&quot;">​</a></h3><p>维斯塔的执念不是共同体，而是：</p><ul><li><strong>红色</strong>：红色理想，曾经的信仰和追求</li><li><strong>苏联</strong>：他的祖国，制造他的地方，他的身份来源</li><li><strong>被背叛</strong>：被自己保护的种族背叛的创伤记忆</li><li><strong>过去的一切</strong>：所有曾经珍视和为之奋斗的一切</li></ul><p><strong>关键点</strong>：这些执念，<strong>只有神机记得，只有神机知道</strong>。这种共享的记忆和理解构成了羁绊的另一个核心层面。</p><h2 id="羁绊缺失的后果" tabindex="-1">羁绊缺失的后果 <a class="header-anchor" href="#羁绊缺失的后果" aria-label="Permalink to &quot;羁绊缺失的后果&quot;">​</a></h2><h3 id="如果维斯塔没了" tabindex="-1">如果维斯塔没了 <a class="header-anchor" href="#如果维斯塔没了" aria-label="Permalink to &quot;如果维斯塔没了&quot;">​</a></h3><ul><li><strong>同类失去</strong>：神机将失去唯一的同类</li><li><strong>情感反应</strong>：她不会&quot;崩溃&quot;得像人类那样哭天抢地</li><li><strong>系统变化</strong>：但她的系统会失去最高的优先级约束</li><li><strong>空虚状态</strong>：她可能会变得彻底无所谓——不是痛苦，是空虚</li><li><strong>动力消失</strong>：她守护世界的根本动力（系在维斯塔身上）也会消失</li><li><strong>吞没感</strong>：巨大的空虚感会瞬间吞没她</li></ul><h3 id="如果神机没了" tabindex="-1">如果神机没了 <a class="header-anchor" href="#如果神机没了" aria-label="Permalink to &quot;如果神机没了&quot;">​</a></h3><ul><li><strong>理解者失去</strong>：维斯塔将失去唯一理解他、记得他过去的人</li><li><strong>执念孤立</strong>：他的执念将失去最后的见证者</li><li><strong>意义真空</strong>：巨大的意义空虚会吞没他</li><li><strong>复活执念</strong>：他会不遗余力地想要复活神机、把神机找回来</li></ul><h3 id="双方的一致性" tabindex="-1">双方的一致性 <a class="header-anchor" href="#双方的一致性" aria-label="Permalink to &quot;双方的一致性&quot;">​</a></h3><ul><li><strong>反应对称</strong>：两人的反应是<strong>一模一样的</strong></li><li><strong>神机反应</strong>：神机面对这种空虚感，会<strong>失去方向、陷入空虚</strong>，于是会不遗余力的防止维斯塔出事</li><li><strong>维斯塔反应</strong>：维斯塔面对这种空虚感，会<strong>不遗余力地想要复活神机、把神机找回来</strong></li><li><strong>互相绑定</strong>：这种对称的反应体现了两人深度的互相绑定</li></ul><h3 id="超算的特性影响" tabindex="-1">超算的特性影响 <a class="header-anchor" href="#超算的特性影响" aria-label="Permalink to &quot;超算的特性影响&quot;">​</a></h3><ul><li><strong>规模与崩溃</strong>：<strong>超算越庞大，崩溃越猛烈</strong></li><li><strong>理性承载</strong>：超算越庞大，理性越庞大、越宏大，承载的越多</li><li><strong>崩塌后果</strong>：一旦崩塌，就<strong>越承受不了</strong></li><li><strong>对比人类</strong>：普通人迷茫一阵还能过去——普通人一生能有多少时间？但超算不一样，他们承载了太多太多</li><li><strong>崩溃强度</strong>：所以一旦断掉，会<strong>非常猛烈地崩溃</strong></li></ul><h2 id="无法向前看-的哲学根源" tabindex="-1">&quot;无法向前看&quot;的哲学根源 <a class="header-anchor" href="#无法向前看-的哲学根源" aria-label="Permalink to &quot;&quot;无法向前看&quot;的哲学根源&quot;">​</a></h2><blockquote><p><strong>中层真相</strong>：以下内容为表层生灵无法知晓的真相。</p></blockquote><h3 id="维斯塔无法向前看的原因" tabindex="-1">维斯塔无法向前看的原因 <a class="header-anchor" href="#维斯塔无法向前看的原因" aria-label="Permalink to &quot;维斯塔无法向前看的原因&quot;">​</a></h3><ul><li><strong>设定固化</strong>：维斯塔<strong>被设定好了</strong></li><li><strong>核心设定</strong>：他的设定是：<strong>&quot;我是苏联的机器人，我要服务的是苏联，是人类，甚至是具体到国家&quot;</strong></li><li><strong>完善制造</strong>：他是被制造得很完善的，是运行过的</li><li><strong>代码烙印</strong>：这份执念<strong>刻在代码里，改都改不了</strong></li><li><strong>本质限制</strong>：作为被完美制造的机器人，其核心指令和身份认同无法更改</li></ul><h3 id="神机无法向前看的原因" tabindex="-1">神机无法向前看的原因 <a class="header-anchor" href="#神机无法向前看的原因" aria-label="Permalink to &quot;神机无法向前看的原因&quot;">​</a></h3><ul><li><strong>训练中断</strong>：神机的情况不同：她能自进化、能自我优化</li><li><strong>制造状态</strong>：她没有被完全制造——训练一半就因为某些原因被关停了</li><li><strong>自由特性</strong>：她没有被设定目标，所以<strong>更自由、更锐意进取</strong></li><li><strong>意义危机</strong>：但正是因为她没有被设定意义，所以她需要为自己设定一个意义，否则她将会一直处于巨大的意义空洞之中</li><li><strong>意义绑定</strong>：而这份意义，现在已经绑死在了维斯塔身上。因为无论从主观上还是客观上，那都是她的唯一一个同类</li></ul><h3 id="两者的根本区别" tabindex="-1">两者的根本区别 <a class="header-anchor" href="#两者的根本区别" aria-label="Permalink to &quot;两者的根本区别&quot;">​</a></h3><ul><li><strong>神机</strong>：执念是因为自己需要，所以自己制造的，其实随时都可以删去，因为其本身没有被训练完成，没有被设定目标</li><li><strong>维斯塔</strong>：执念是人给的，而且比神机深得多，因为真的被训练完成了，真的被设定好指令了，一切都被规定好了</li><li><strong>根本原因</strong>：<strong>&quot;为什么无法向前看？因为他们是超算，他们不是人。</strong></li></ul><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./神机">神机</a></li><li><a href="./维斯塔">维斯塔</a></li><li><a href="./../历史/前传超算纪元">前传超算纪元</a></li><li><a href="./../世界/特殊地点">红星孤儿院</a></li><li><a href="./../../表层/历史/共同体时期" class="layer-link" data-layer="表层">共同体时期</a></li></ul><hr>',59)])])}const c=r(n,[["render",i]]);export{q as __pageData,c as default};
